import{_ as l,c as i,o as e,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山火贲","description":"周易折中 - 山火贲","frontmatter":{"title":"山火贲","description":"周易折中 - 山火贲"},"headers":[],"relativePath":"zh/classics/zhezhong/028.md","filePath":"zh/classics/zhezhong/028.md"}'),h={name:"zh/classics/zhezhong/028.md"};function p(n,a,d,t,s,o){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="山火贲" tabindex="-1">山火贲 <a class="header-anchor" href="#山火贲" aria-label="Permalink to “山火贲”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>贲序卦：嗑者，合也。物不可以苟合而已，故受之以贲。贲者，饰也。物之合则必有文，文乃饰也。如人之合聚，则有威仪；上下物之合聚，则有次序行列。合则必有文也，贲所以次噬嗑也。为卦山下有火，山者，草木百物之所聚也。下有火，则照见其上，草木品彚皆被其光彩，有贲饰之象，故为贲也。</p><p>贲：亨，小利有攸往</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>贲，饰也。卦自损来，者柔自三来而文二，刚自二上而文三。自既济来者，柔自上来而文五，刚自五上而文上。又内离而外艮，有文明而各得其分之象，故为贲。占者以其柔来文刚，阳得阴助而离明于内，故为亨。以其刚上文柔，而艮止于外，故小利有攸往。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>物有饰而后能亨，故曰“无本不立，无文不行”。有实而加饰，则可以亨矣。文饰之道，可增其光彩，故能小利于进也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰：徒质则不能亨，质而有文以加饰之，则可亨，故曰“贲亨”。然文盛则实必衰，苟专尚文以往，则流，故曰“小利有攸往”。小者，谓不可太过以灭其质也。</li></ul><p>王氏申子曰：徒质则不能亨，质而有文以加饰之，则可亨，故曰“贲亨”。然文盛则实必衰，苟专尚文以往，则流，故曰“小利有攸往”。小者，谓不可太过以灭其质也。</p><ul><li>梁氏寅曰：贲者，文饰之道也。有质而加之文，斯可亨矣。朝廷文之以仪制而亨焉，宾主文之以礼貎而亨焉，家人文之以伦序而亨焉，官府文之以教令而亨焉。推之事物，凡有质者无不待于文也。文则无不亨也。然既亨矣，而曰“小利有攸往”，何也？文饰之道但加之文采耳，非能变其实也，故文之过盛非所利也，但小利于有往而已矣。世之不知本者，或忘其当务之急，而屑屑焉于文饰，虽欲其亨，亦安得而亨乎？</li></ul><p>梁氏寅曰：贲者，文饰之道也。有质而加之文，斯可亨矣。朝廷文之以仪制而亨焉，宾主文之以礼貎而亨焉，家人文之以伦序而亨焉，官府文之以教令而亨焉。推之事物，凡有质者无不待于文也。文则无不亨也。然既亨矣，而曰“小利有攸往”，何也？文饰之道但加之文采耳，非能变其实也，故文之过盛非所利也，但小利于有往而已矣。世之不知本者，或忘其当务之急，而屑屑焉于文饰，虽欲其亨，亦安得而亨乎？</p><ul><li>张氏振渊曰：离德文明，莫掩则无径情直行之毙，行之可通，故亨。艮德止而不过，又有不尽饰之象焉，故用文者亦但可少有所饰，不可务为尽饰以戕其本真，故曰“小利有攸往”。</li></ul><p>张氏振渊曰：离德文明，莫掩则无径情直行之毙，行之可通，故亨。艮德止而不过，又有不尽饰之象焉，故用文者亦但可少有所饰，不可务为尽饰以戕其本真，故曰“小利有攸往”。</p><p>象曰：山下有火，贲；君子以明庶政，无敢折狱</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>山下有火，明不及远，明庶政事之小者，折狱事之大者。内离明而外艮止，故取象如此。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>山者，草木百物之所聚生也。火在其下而上照，庶类皆被其光明，为贲饰之象也。君子观山下有火、明照之象，以脩明其庶政，成文明之治，而无敢果于折狱也。折狱者，人君之所致愼也，岂可恃其明而轻自用乎？乃圣人之用心也，为戒深矣。象之所取，惟以山下有火、明照庶物，以用明为戒；而贲亦自有无敢折狱之义。折狱者，专用情实，有文饰则没其情矣，故无敢用文以折狱也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：处贲之时，止物以文明，不可以威刑，故君子以明庶政而无敢折狱。</p></li><li><p>朱子语类 ：问：明庶政无敢折狱。 曰：此与旅卦都说刑狱事，但争艮与离之在内外，故其说相反。止在外，明在内，故明政而不敢折狱；止在内，明在外，故明谨用刑而不敢留狱。如今州县治狱，禁勘审覆，自有许多节次，过乎此而不决，便是留狱；不及乎此而决，便是敢于折狱。尚书要囚至于旬时，他须有许多时日，与周礼秋官同意。</p></li><li><p>问：明庶政无敢折狱。 曰：此与旅卦都说刑狱事，但争艮与离之在内外，故其说相反。止在外，明在内，故明政而不敢折狱；止在内，明在外，故明谨用刑而不敢留狱。如今州县治狱，禁勘审覆，自有许多节次，过乎此而不决，便是留狱；不及乎此而决，便是敢于折狱。尚书要囚至于旬时，他须有许多时日，与周礼秋官同意。</p></li><li><p>蔡氏渊曰 ：有山之材而照之以火，则光彩外著，贲之象也。明庶政，离明象政者治之具，所当文饰也；无敢折狱，艮止象折狱贵乎情实，贲则文饰而没其情矣。</p></li><li><p>何氏楷曰 ：吕刑曰：“非佞折狱，惟良折狱。”苟恃其明察而缘饰以没其情，民且有含冤矣。故言刻核者曰深文，言锻錬者曰文致，法曰文网，弄法者曰舞文。治狱之多冤，未有不起于文者，此皆敢心误之也。</p></li></ul><p>彖曰：贲亨</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>亨字疑衍。</p><p>柔来而文刚，故亨；分刚上而文柔，故小利有攸往，天文也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦变释卦辞。刚柔之交，自然之象，故曰“天文”。先儒说，“天文”上当有“刚柔交错”四字，理或然也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：《易》有刚柔往来上下相易之说，而其最著者，《贲》之《彖传》也。故学者沿是争推其所从变，曰泰变为贲，此大惑也。一卦之变为六十三，岂独为贲也哉？徒知泰之为贲，又乌知贲之不为泰乎？凡《易》之所谓刚柔往来相易者，皆本诸乾坤也。</p></li><li><p>胡氏炳文曰：柔来而文刚，是以刚为主也。刚往文柔，必曰“分刚上而文柔”者，亦以刚为主也。故《本义》于柔文刚则曰阳得阴助，于刚文柔而不曰阴得阳助。</p></li><li><p>何氏楷曰：刚为质，柔为文。柔来文刚，是本先立矣而文行焉，故亨。分刚上而文柔者，非以刚为文也，分刚画居上而柔始得成其文。</p></li><li><p>张氏振渊曰：柔来文刚，是当质胜之馀而以文济之；刚上文柔，是当文胜之后而以质救之。二者皆以质为主。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>亨与小利有攸往皆指文而言之。故柔来而文刚者，见刚当以柔济之而后可通也；刚上文柔者，见柔当以刚节之，而柔之道不可纯用以行也。何氏、张氏质文之说极明。</p><p>又案，刚上文柔而曰“分”者，本于内之诚实以为节，文之则乃是由中而分出者，故曰“分”也。</p><p>文明以止，人文也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>又以卦德言之。止，谓各得其分。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>卦为贲饰之象，以上下二体刚柔交相为文饰也。下体本乾，柔来文其中而为离；上体本坤，刚往文其上而为艮。乃为山下有火，止于文明而成贲也。天下之事无饰不行，故贲则能亨也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：文明，离也；以止，艮也。用此文明之道，裁止于人是人之文德之教。</p></li><li><p>胡氏允曰：君臣父子兄弟夫妇朋友粲然有礼以相接者，文之明也；截然有分以相守者，文之止也。</p></li><li><p>王氏应麟曰：大畜为学，贲为文。能止健而后可以为学，文明以止而后可以为文者，笃实而已。不以笃实为本，则学不足以成德，文不足以明理。</p></li><li><p>何氏楷曰：止者，限而不过之谓。一文之一止之而文成，礼以节文为训，即此意。</p></li></ul><p>观乎天文以察时变，观乎人文以化成天下</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>极言贲道之大也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>天文谓日月星辰之错列，寒暑阴阳之代变，观其运行以察四时之迁改也。人文，人理之伦序。观人文以教化天下，天下成其礼俗，乃圣人用贲之道也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏应麟曰：天文，天之理也；人文，人之道也。圣人能观天文以察时变，观人文以化成天下。</p></li><li><p>朱氏熹曰：天文者，自然之序；人文者，人事之宜。圣人仰观天文，俯察地理，中知人事，故能尽物之性，赞天地之化育，而化成天下。</p></li><li><p>程氏颐曰：观天文，知天道之流行；观人文，知人道之伦序。圣人因天道以立人道，因天文以立人文，故能成其化育之功。</p></li><li><p>张氏载曰：天文者，日月星辰之运行也；人文者，礼乐制度之兴作也。天文以明时变，人文以化民俗，皆圣人之所宜观也。</p></li></ul><p>初九：贲其趾，舍车而徒</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>刚德明体，自贲于下，为舍非道之车而安于徒步之象。占者自处当如是也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初九以阳刚居明体而处下，君子有刚明之德而在下者也。君子在无位之地，无所施于天下，唯自贲饰其所行而已。趾取在下而所以行也，君子脩饰之道，正其所行，守节处义。其行不苟，义或不当，则舍车舆而宁徒行。众人之所羞，而君子以为贲也。舍车而徒之义，兼于比应。取之初比二而应四，应四正也，与二非正也。九之刚明守义，不近与于二，而远应于四，舍易而从难，如舍车而徒行也。守节义，君子之贲也。是故君子所贲，世俗所羞；世俗所贵，君子所贱。以车徒为言者，因趾与行为义也。</p><p>象曰：舍车而徒，义弗乘也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>君子之取舎，决于义而已。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>舎车而徒行者，于义不可以乘也。初应四正，从二非正也。近舎二之易而从四之难，舎车而徒行也。君子之贲，守其义而已。</p><p>六二：贲其须</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>二以阴柔居中正，三以阳刚而得正，皆无应与，故二附三而动，有贲湏之象。占者宜从上之阳刚而动也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>卦之为贲，虽由两爻之变，而文明之义为重。二实贲之主也，故主言贲之道。饰于物者，不能大变其质也，因其质而加饰耳，故取须义。须随颐而动者也，动止唯系于所附，犹善恶不由于贲也。二之文明，唯为贲饰，善恶则系其质也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：得其位而无应，三亦无应，俱无应而比焉，近而相得者也。须之为物，上附者也，故曰“贲其须”。</p></li><li><p>朱氏震曰 ：毛在颐曰须，在口曰髭，在颊曰髯。三至上有颐体，二在颐下，须之象也。二三刚柔相贲，贲其须也。夫文不虚生，须生于颐，须所以贲其颐也。</p></li><li><p>俞氏琰曰 ：二无应而比三，三亦无应而比二，故与之相贲。贲以柔来文刚，故亨。文当从质，非质则不能自饰；阴必从阳，非阳则不能自进。六二纯柔，必待九三之动而后动，故曰“贲其须”。</p></li><li><p>蒋氏悌生曰 ：六以二居中，故有贲须之象。须于人身无损益于躯体，但可为仪表之饰。周旋揖譲，进退低昻，皆随面貎而动，使人仪举者文采容止可观，故象曰“与上兴也”。</p></li><li><p>何氏楷曰 ：须，阴血之形而柔，所以文刚者。然阴柔不能自动，必附丽于阳，如须虽有美，必附丽于颐也。大抵刚为质，柔为文，文不附质，焉得为文？故二必贲其须以从三，五必贲于丘园以从上。圣人右质左文之意，于此可见。</p></li></ul><p>象曰：贲其须，与上兴也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>以须为象者，谓其与上同兴也。随上而动，动止唯系所附也。犹加饰于物，因其质而贲之，善恶在其质也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰 ：自三至上有颐之象，二在颐下，须之象也。上无其应，三亦无应，若能上承于三，与之同徳，虽俱无应，可相与而兴起也。</p></li><li><p>袁氏枢曰 ：阴不能以自明，得阳而后明；柔不能以自立，得刚而后立；下不能以自兴，得上而后兴也。</p></li><li><p>沈氏一贯曰 ：上无正应而从乎三，故曰与上兴，贵从阳也。</p></li></ul><p>九三：贲如濡如，永贞吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>一阳居二阴之闲，得其贲而润泽者也。然不可溺于所安，故有永贞之戒。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三处文明之极，与二四二阴闲处相贲，贲之盛者也。故云“贲如”，“如”辞助也。贲饰之盛，光彩润泽，故云“濡如”。光彩之盛，则有润泽。诗云“麀鹿濯濯”。永贞吉，三与二四非正应，相比而成相贲，故戒以常永贞。正贲者饰也，贲饰之事难乎常也，故永贞则吉。三与四相贲，又下比于二，二柔文一刚，上下交贲，为贲之盛也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：互坎有濡义，亦有陷义。既未济“濡首濡尾”，濡而陷者也。九三非不贞也，能永其贞，则二阴于我为润泽之濡，我于彼不为陷溺之濡矣。</p></li><li><p>俞氏琰曰 ：九三处六二六四之闲，故曰“贲如濡如”。文过则质丧，质丧则文弊，要当永久以刚正之德固守，则吉。</p></li><li><p>潘氏士藻曰 ：三本刚正，特虑其为二阴所陷溺，未免有灭质之患，故有永贞之戒。</p></li><li><p>何氏楷曰 ：以一刚介二柔之闲，贲之盛者也。曰“濡如”者，犹诗言“六辔如濡”，谓所饰之文采鲜泽也。然受物之饰，恐为物溺，故戒之曰“永贞吉”。长守其阳刚之正，而不为阴柔所溺，则不至以文灭质矣。</p></li></ul><p>象曰：永贞之吉，终莫之陵也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>饰而不常，且非正人所陵侮也。故戒能永正则吉也，其贲既常而正，谁能陵之乎？</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏渊曰 ：陵侮也，三能永贞，则二柔虽比己而濡如，然终莫之陵侮而不至陷溺也。</p></li><li><p>沈氏一贯曰 ：下三爻皆取离义，至三而文明极矣，有溺质之象。惟永贞则济之以艮止，故吉而莫之陵。</p></li></ul><p>六四：贲如皤如，白马翰如，匪寇婚媾。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>皤，白也。马人所乘，人白则马亦白矣。四与初相贲者，乃为九三所隔而不得遂，故皤如而其往求之心如飞翰之疾也。然九三刚正，非为寇者也，乃求婚媾耳，故其象如此。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四与初为正应相贲者也，本当贲如而为三所隔，故不获相贲而皤如。皤，白也，未贲也。马在下而动者也，未贲相贲，故云“白马”。其从正应之志如飞，故云“翰如”。匪为九三之寇仇所隔，则婚媾遂其相亲矣。己之所乘与动于下者，马之象也。初四正应，终必贲亲，第始为其间隔耳。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云 ：六四“白马翰如”，言此爻无所贲饰，其马亦白也。言无饰之象如此。</p></li><li><p>胡氏炳文曰 ：屯二应五，下求上也不可以急；贲四应初，上求下也不可以缓。</p></li><li><p>俞氏琰曰 ：发白为皤，马白为翰。</p></li><li><p>《礼记》云 ：“商人尚白，戎事乘翰。”</p></li><li><p>郑氏注云 ：“翰，马白色也。”四当贲道之变，文返于质，故其象如此。</p></li><li><p>梁氏寅曰 ：六四在离明之外，为艮止之始，乃贲之盛极而当反质素之时也，故云“贲如皤如”。夫初之舍车，为在下而无所乘故也；四在九三之上，则有所乘矣，故云“白马翰如”。人既质素，则马亦白也。</p></li><li><p>苏氏浚曰 ：六四一爻，当以“白贲”之义推之。四与初相贲者也，以实心而求于初，不为虚饰。初曰“贲趾”，四曰“皤如”，初曰“舍车”，四曰“白马”，同一“白贲”之风而已。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>程传沿注䟽之说，本义又沿程传之说，皆以为初四相贲而为三所隔，故未得其贲而皤然也。然朱子语类以无饰言之，则已自改其说矣。故以后诸儒皆以皤白为崇素返质之义，实于卦意为合。又案易中凡重言如者，皆两端不定之辞。故屯如邅如者，欲进而未径进也；此三爻贲如濡如者，得阴自贲又虑其见濡也；此爻贲如皤如者，当贲之时既外尚乎文饰而下应初刚又心崇乎质素，两端未能自决，象传谓之疑者此也。白马翰如指初九也，已有皤如之心，故知白马翰如而来者匪寇也，乃己之婚媾也。凡言匪寇婚媾，皆就上文所指之物而言，屯二、睽上与此正同。</p><p>象曰：六四当位疑也，匪寇婚媾，终无尤也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>当位疑，谓所当之位可疑也；终无尤，谓若守正而不与，亦无他患也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四与初相远，而三介于其闲，是所当之位为可疑也。虽为三寇仇所隔，未得亲于婚媾，然其正应理直义胜，终必得合，故云终无尤也。尤怨也，终得相贲，故无怨尤也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：纯白无伪，谁能闲之？始疑而终合，故曰终无尤也。</p></li><li><p>郭氏雍曰 ：四虽自饰，亦有皤如之质，犹丘园之贲，虚已待物之象也。初饰其趾而来，翰如之马也，以刚下柔而来应，匪寇也，婚媾之道也。四虽怀疑，终何尤哉？</p></li></ul><p>六五：贲于丘园，束帛戋戋，吝终吉。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>六五柔中，为贲之主，敦本尚实，得贲之道，故有丘园之象。然阴性吝啬，故有束帛戋戋之象。束帛薄物，戋戋浅小之意。人而如此，虽可羞吝，然礼奢宁俭，故得终吉。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五以阴柔之质，密比于上九刚阳之贤。阴比于阳，复无所系应，从之者也。受贲于上九也。自古设险守国，故城垒多依丘坂。丘谓在外而近且高者，园圃之地最近城邑，亦在外而近者。丘园谓在外而近者，指上九也。六五虽居君位而阴柔之才不足自守，与上之刚阳相比而志从焉。贲于外，比之贤，贲于丘园也。若能受贲于上九，受其裁制，如束帛而戋戋，则虽其柔弱不能自为，为可吝少。然能从于人，成贲之功，终得其吉也。戋戋，翦裁分裂之状。帛未用则束之，故谓之束帛。及其制为衣服，必剪裁分裂，戋戋然。束帛喻六五本质，戋戋谓受人翦制而成用也。其资于人与蒙同，而蒙不言吝者，盖童蒙而赖于人乃其宜也，非童幼而资贲于人为可吝耳。然享其功终为吉也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问：“贲于丘园”，安定作敦本说... 曰：“某之意正要如此。”或以戋戋为盛多之貌，非也。戋戋者，浅小之意，所以下文云“吝终吉”。吝者虽不好看，然终却吉。 又云：“贲于丘园，束帛戋戋，是个务农尚俭。”戋戋是狭小不足之意，以字义考之，从水则为浅，从贝则为贱，从金则为钱。六五居尊位，而如此敦本尚俭，便似吝啬。如卫文公、汉文帝虽是吝，终吉。此在贲卦有反本之意。 问：“六五是在艮体，故安止于丘园而不复外贲之象。” 曰：“亦是上比于九，渐渐到极处。若一向贲饰去，亦自不好，须是收敛方得。”</p></li><li><p>问：“贲于丘园”，安定作敦本说... 曰：“某之意正要如此。”或以戋戋为盛多之貌，非也。戋戋者，浅小之意，所以下文云“吝终吉”。吝者虽不好看，然终却吉。</p></li><li><p>又云：“贲于丘园，束帛戋戋，是个务农尚俭。”戋戋是狭小不足之意，以字义考之，从水则为浅，从贝则为贱，从金则为钱。六五居尊位，而如此敦本尚俭，便似吝啬。如卫文公、汉文帝虽是吝，终吉。此在贲卦有反本之意。</p></li><li><p>问：“六五是在艮体，故安止于丘园而不复外贲之象。” 曰：“亦是上比于九，渐渐到极处。若一向贲饰去，亦自不好，须是收敛方得。”</p></li><li><p>胡氏炳文曰 ：不贲于市朝而贲于丘园，敦本也；束帛戋戋，尚实也。</p></li><li><p>潘氏士藻曰 ：五居中履尊，下无应与而上比文柔之刚，得止之义，以成贲之道，故有贲于丘园之象。</p></li><li><p>何氏楷曰 ：比于上九刚阳之贤，受贲于上九者也。丘园指上九，阳刚而处外，乃贤人隐丘园之象。据彖曰“刚上文柔”，则六五乃上所贲者。爻所谓“贲于丘园”，犹曰受贲饰于丘园也。按昏礼纳帛一束，束五两，注：“十端为束。”束帛戋戋，其仪文虽薄，然终与上合志而吉。</p></li></ul><p>象曰：六五之吉，有喜也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>能从人以成贲之功，享其吉美，是有喜也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>方氏应祥曰 ：于文胜之时而为丘园之贲，岂不甚可喜乎？非自喜也，为世道喜也。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>传于五位多言有庆，庆大而喜小也。此爻居尊而返朴崇俭，亦可以易俗移风，而但曰有喜者，且就一身无过言尔。如无妄五、损四、兑四之例，皆以无疾为喜，若推其用，则化成天下，庆在其中矣。</p><p>上九：白贲无咎</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>贲极反本，复于无色，善补过矣，故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上九，贲之极也。贲饰之极，则失于华伪。唯能质白其贲，则无过失之咎。白，素也，尚质素则不失其本真。所谓尚质素者，非无饰也，不使华没实耳。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问如本义说，六五、上九两爻却是贲极反本之意。曰：“六五已有反本之渐，故曰‘贲于丘园，束帛戋戋’。至上九‘白贲’，则反本而复于无饰矣。盖皆贲极之象也。”</p></li><li><p>王氏申子曰 ：上以阳刚为成卦之主，居艮止之极，当贲道之终。止文之流于终，终则返而质矣。故贲道成而无弊，无弊故无咎。</p></li><li><p>熊氏良辅曰 ：白贲云者，终归于无所饰也。贲之取义，始则因天下之质而饰之以文，终则反天下之文而归之以质。</p></li><li><p>胡氏炳文曰 ：贲上卦言白马，言束帛戋戋，终言白贲。《杂卦》曰：“贲，无色也。”可谓一言以蔽之矣。</p></li><li><p>蒋氏悌生曰 ：六五、上九皆敦尚质素，以白为贲，素以为绚之意。上九处无位之地，高尚其事，不尚华饰，以质素为贲，甘受和、白受采，其贤于五采彰施远矣。</p></li></ul><p>象曰：白贲无咎，上得志也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>白贲无咎，以其在上而得志也。上九为得志者，在上而文柔成贲之功，六五之君又受其贲，故虽居无位之地而实尸贲之功，为得志也。与他卦居极者异矣。既在上而得志，处贲之极，将有华伪失实之咎，故戒以质素则无咎，饰不可过也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 问：何谓得志？ 曰：居卦之上，在事之外，不假文饰而有自然之文，便是优游自得也。</p></li><li><p>问：何谓得志？ 曰：居卦之上，在事之外，不假文饰而有自然之文，便是优游自得也。</p></li><li><p>项氏安世曰 ：六二柔来而文刚，主内卦之文者也。内卦以文为文，故曰“贲其须”。须之丽于身，最为虚文也。然阳气不盛，不足以贲其须，故曰“与上兴也”。二与上交而成卦，二以上为主，犹须以阳为主也。深明文之与质未尝相离，故不言吉凶，吉凶系于质也。上九分刚上而文柔，主外卦之文者也。外卦以质为文，故曰“白贲”。白本非所以为文也，然文之初兴必自质始，则白固在众采之先；文之既极必以质终，则白又在众采之后。是则白者，贲之所成终而所成始也。故曰“上得志也”，以其在卦之终，主贲之成，是以得遂其笃实之志。深明质之与文未尝相悖，故言“无咎”。盖行与时违，疑于有咎也。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>项氏以“与上兴”为上九，不如指九三言为当。上九居卦之极，文之极而返于质，故曰“白贲”。白贲为质素之至，故无咎。而九三虽与上相应，但处内卦之中，故言“与上兴”以喻其随阳而动，顺应时势之义。</p><p>总论</p><ul><li>丘氏富国曰 ：“阴阳二物，有应者以应而相贲，无应者以比而相贲。四与初应，求贲于初，故初‘贲趾’而四‘翰如’也。二比三而贲乎三，故二‘贲须’而三‘濡如’也。五比上而贲乎上，故五‘贲丘园’而上‘白贲’也。初与四应而相贲者也，二与三、五与上比而相贲者也，此贲六爻之大旨也。”龚氏焕曰：“贲之为言饰也，谓饰以文华也。然以六爻考之，初之‘舍车而徒’、五之‘丘园’、上之‘白贲’，皆质实而不事文华者也。四之‘皤如’、贲于初，二之‘贲须’附于三，惟三之‘贲如濡如’，乃贲饰之盛，而即有永贞之戒者，惧其溺于文也。如是，则古人之所贲者，未始事文华也，亦务其本实而已。本实既立，文华不外焉。徒事文华，不务本实，非古人所谓贲。”</li></ul>',127)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
